import math
from itertools import product

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_task():
    # Target ratio: 3 + 2*sqrt(2) approx 5.8284
    target_ratio = 3 + 2 * math.sqrt(2)

    found_solutions = []

    # Search range: d up to 10, and c proportionally around 5.828*d
    MAX_D = 10
    C_MARGIN = 4 # Search C in range [ceil(5.828*d) - M, ceil(5.828*d) + M]

    for d in range(1, MAX_D + 1):
        # Determine a search window for c
        c_start = max(1, math.floor(target_ratio * d) - C_MARGIN)
        c_end = math.ceil(target_ratio * d) + C_MARGIN

        for c in range(c_start, c_end + 1):
            if c <= d:
                continue # Condition c > d

            if math.gcd(c, d) != 1:
                continue # Primary solution check

            # Diophantine equation check: c^2 - 6cd + d^2 = m^2
            m_squared = c*c - 6*c*d + d*d

            if is_square(m_squared):
                # Solution found: (c, d)
                E = c/d + d/c
                found_solutions.append({
                    'c': c, 
                    'd': d, 
                    'm_squared': m_squared, 
                    'E': E
                })

    print("--- Found Primary Solutions (c > d) ---")
    if not found_solutions:
        print("No solutions found in the limited search range.")
    else:
        for sol in found_solutions:
            print(f"c={sol['c']}, d={sol['d']}, m^2={sol['m_squared']}, E={sol['E']:.6f}")

solve_task()
